import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, float, mix, sin, fract } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const pos = config.scenePosition ?? { x: 3.2, y: -0.3, z: 0 };
  const rot = config.sceneRotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale ?? { x: 1, y: 1, z: 1 };
  const atlas = config.atlas ?? { index: 0, sourceRect: [0, 0, 512, 320] };

  const tex = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');

  const [sx, sy, sw, sh] = atlas.sourceRect;
  const atlasW = 512;
  const atlasH = 320;
  const u0 = sx / atlasW;
  const v0 = sy / atlasH;
  const u1 = (sx + sw) / atlasW;
  const v1 = (sy + sh) / atlasH;

  const aspect = sw / sh;
  const planeW = 1.6;
  const planeH = planeW / aspect;

  const geom = new THREE.PlaneGeometry(planeW, planeH);

  // Atlas-aware UV remap so we only sample the source rect region.
  const remapUV = vec2(
    mix(float(u0), float(u1), uv().x),
    mix(float(v0), float(v1), uv().y)
  );

  const sampled = texture(tex, remapUV);

  // Static subtle grain — engineered, non-animated surface texture.
  const seed = uv().x.mul(12.9898).add(uv().y.mul(78.233));
  const grainAmt = fract(sin(seed).mul(43758.5453)).sub(0.5).mul(0.03);
  const colorNode = sampled.rgb.add(vec3(grainAmt, grainAmt, grainAmt));

  const mat = new THREE.MeshBasicNodeMaterial();
  mat.colorNode = colorNode;
  mat.transparent = true;
  mat.opacityNode = new THREE.UniformNode(0);

  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);

  mesh.userData.handlers = {};

  // fade-up entry preset (opacity 0 -> 1, y +0.2 -> 0, power2.out, 0.5s)
  const tl = gsap.timeline();
  tl.to(mat.opacityNode, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.from(mesh.position, { y: pos.y + 0.2, duration: 0.5, ease: 'power2.out' }, 0);

  mesh.userData.cleanup = () => {
    tl.kill();
    geom.dispose();
    mat.dispose();
  };

  return mesh;
}
